package reliquary.entity.shot;

import net.minecraft.core.Direction;
import net.minecraft.core.particles.ColorParticleOption;
import net.minecraft.core.particles.ParticleOptions;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.projectile.Projectile;
import net.minecraft.world.item.alchemy.PotionContents;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.*;
import reliquary.init.ModEntities;
import reliquary.reference.Config;
import reliquary.util.RegistryHelper;
import reliquary.util.potions.PotionHelper;

import javax.annotation.Nullable;

import java.util.*;

@SuppressWarnings("squid:S2160")
public abstract class ShotBase extends Projectile {
	private static final EntityDataAccessor<Byte> CRITICAL = SynchedEntityData.defineId(ShotBase.class, EntityDataSerializers.BYTE);
	private static final EntityDataAccessor<Integer> COLOR = SynchedEntityData.defineId(ShotBase.class, EntityDataSerializers.INT);
	private PotionContents potionContents = PotionContents.EMPTY;

	protected int ticksInAir = 0;

	private int ricochetCounter = 0;
	private boolean scheduledForDeath = false;

	protected <T extends ShotBase> ShotBase(EntityType<T> entityType, Level level) {
		super(entityType, level);
	}

	protected <T extends ShotBase> ShotBase(EntityType<T> entityType, Level level, Player player, InteractionHand hand) {
		this(entityType, level);
		setOwner(player);
		moveTo(player.getX(), player.getY() + player.getEyeHeight(), player.getZ(), player.getYRot(), player.getXRot());
		setPos(getX() - Mth.cos(getYRot() / 180.0F * (float) Math.PI) * (hand == InteractionHand.MAIN_HAND ? 1 : -1) * 0.16F, getY() - 0.2D,
				getZ() - Mth.sin(getYRot() / 180.0F * (float) Math.PI) * (hand == InteractionHand.MAIN_HAND ? 1 : -1) * 0.16F);
	}

	protected Optional<Player> getShooterPlayer() {
		return Optional.ofNullable((Player) getOwner());
	}

	@Override
	protected void defineSynchedData(SynchedEntityData.Builder builder) {
		builder.define(CRITICAL, (byte) 0);
		builder.define(COLOR, 0);
	}

	public ShotBase addPotionContents(PotionContents potionContents) {
		if (potionContents.hasEffects()) {
			this.potionContents = potionContents;
			entityData.set(COLOR, potionContents.getColor());
		}

		return this;
	}

	@Override
	public void shoot(double motionX, double motionY, double motionZ, float velocity, float inaccuracy) {
		float var9 = (float) Math.sqrt(motionX * motionX + motionY * motionY + motionZ * motionZ);
		motionX /= var9;
		motionY /= var9;
		motionZ /= var9;
		motionX += random.nextGaussian() * 0.0075D * inaccuracy;
		motionY += random.nextGaussian() * 0.0075D * inaccuracy;
		motionZ += random.nextGaussian() * 0.0075D * inaccuracy;
		motionX *= velocity;
		motionY *= velocity;
		motionZ *= velocity;
		setDeltaMovement(motionX, motionY, motionZ);
		float var10 = (float) Math.sqrt(motionX * motionX + motionZ * motionZ);
		setYRot((float) (Math.atan2(motionX, motionZ) * 180.0D / Math.PI));
		setXRot((float) (Math.atan2(motionY, var10) * 180.0D / Math.PI));
		yRotO = getYRot();
		xRotO = getXRot();
	}

	@Override
	public void lerpMotion(double motionX, double motionY, double motionZ) {
		setDeltaMovement(motionX, motionY, motionZ);

		if (xRotO == 0.0F && yRotO == 0.0F) {
			float var7 = (float) Math.sqrt(motionX * motionX + motionZ * motionZ);
			setYRot((float) (Math.atan2(motionX, motionZ) * 180.0D / Math.PI));
			setXRot((float) (Math.atan2(motionY, var7) * 180.0D / Math.PI));
			yRotO = getYRot();
			xRotO = getXRot();
			moveTo(getX(), getY(), getZ(), getYRot(), getXRot());
		}
	}

	/**
	 * Called to update the entity's position/logic. Special snippets of the usual projectile code have been removed so they can be handled manually in the
	 * onImpact methods of the base shot.
	 */
	@Override
	public void tick() {
		super.tick();
		if (ticksInAir > 200) {
			discard();
		}

		if (level().isClientSide) {
			spawnPotionParticles();
		}
		Vec3 motionVec = getDeltaMovement();
		if (xRotO == 0.0F && yRotO == 0.0F) {
			float pythingy = (float) Math.sqrt(motionVec.x() * motionVec.x() + motionVec.z() * motionVec.z());
			setYRot((float) (Math.atan2(motionVec.x(), motionVec.z()) * 180.0D / Math.PI));
			setXRot((float) (Math.atan2(motionVec.y(), pythingy) * 180.0D / Math.PI));
			yRotO = getYRot();
			xRotO = getXRot();
		}

		++ticksInAir;
		if (ticksInAir == 2) {
			level().addParticle(ParticleTypes.FLAME, getX() + smallGauss(0.1D), getY() + smallGauss(0.1D), getZ() + smallGauss(0.1D), 0D, 0D, 0D);
			for (int particles = 0; particles < 3; particles++) {
				doFiringEffects();
			}

		} else {
			doFlightEffects();
		}

		Vec3 posVector = new Vec3(getX(), getY(), getZ());
		Vec3 approachVector = new Vec3(getX() + motionVec.x(), getY() + motionVec.y(), getZ() + motionVec.z());

		HitResult objectStruckByVector = level().clip(new ClipContext(posVector, approachVector, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));

		Entity hitEntity = getHitEntity(motionVec, posVector, approachVector);

		if (hitEntity != null) {
			objectStruckByVector = new EntityHitResult(hitEntity);
		}

		// noinspection ConstantConditions - level.rayTraceBlocks can still produce null under certain conditions
		if (objectStruckByVector != null) {
			applyPotionEffects(objectStruckByVector);
			onHit(objectStruckByVector);
		}

		if (scheduledForDeath) {
			discard();
		}

		Vec3 newPos = position().add(getDeltaMovement());
		setPos(newPos.x, newPos.y, newPos.z);
	}

	@Nullable
	private Entity getHitEntity(Vec3 motionVec, Vec3 posVector, Vec3 approachVector) {
		Entity hitEntity = null;
		List<Entity> struckEntitiesInAABB = level().getEntities(this, getBoundingBox().expandTowards(motionVec).inflate(1.0D, 1.0D, 1.0D));
		double var7 = 0.0D;
		Iterator<Entity> struckEntityIterator = struckEntitiesInAABB.iterator();
		float var11;

		while (struckEntityIterator.hasNext()) {
			Entity struckEntity = struckEntityIterator.next();
			if (struckEntity.isPickable() && (struckEntity != getOwner() || ticksInAir >= 5)) {
				var11 = 0.5F;
				AABB var12 = struckEntity.getBoundingBox().inflate(var11, var11, var11);
				Optional<Vec3> hitResult = var12.clip(posVector, approachVector);

				if (hitResult.isPresent()) {
					double var14 = posVector.distanceTo(hitResult.get());

					if (var14 < var7 || var7 == 0.0D) {
						hitEntity = struckEntity;
						var7 = var14;
					}
				}
			}
		}
		return hitEntity;
	}

	private void spawnPotionParticles() {
		int color = getColor();

		if (color != 0) {
			for (int j = 0; j < 2; ++j) {
				level().addParticle(ColorParticleOption.create(ParticleTypes.ENTITY_EFFECT, color), getX() + (random.nextDouble() - 0.5D) * getBbWidth(),
						getY() + random.nextDouble() * getBbHeight(), getZ() + (random.nextDouble() - 0.5D) * getBbWidth(), 0, 0, 0);
			}
		}
	}

	public int getColor() {
		return entityData.get(COLOR);
	}

	private void applyPotionEffects(HitResult objectStruckByVector) {
		if (objectStruckByVector.getType() == HitResult.Type.ENTITY) {
			EntityHitResult entityStruckResult = ((EntityHitResult) objectStruckByVector);
			if (entityStruckResult.getEntity() instanceof LivingEntity living && potionContents.hasEffects()) {
				PotionHelper.applyEffectsToEntity(potionContents, this, getOwner(), living);
			}
		}
	}

	@Override
	protected void readAdditionalSaveData(CompoundTag compound) {
		potionContents = PotionHelper.getPotionContentsFromCompoundTag(compound);
	}

	@Override
	protected void addAdditionalSaveData(CompoundTag compound) {
		PotionHelper.addPotionContentsToCompoundTag(compound, potionContents);
	}

	@Override
	protected MovementEmission getMovementEmission() {
		return MovementEmission.NONE;
	}

	@Override
	public boolean shouldRenderAtSqrDistance(double distance) {
		double d0 = 64.0D;
		return distance < d0 * d0;
	}

	/**
	 * If returns false, the item will not inflict any damage against entities.
	 */
	@Override
	public boolean isAttackable() {
		return false;
	}

	// these are just simulated dice rolls, they make it slightly easier to
	// adjust damage
	int d3() {
		return random.nextInt(3) + 1;
	}

	int d6() {
		return random.nextInt(6) + 1;
	}

	int d12() {
		return random.nextInt(12) + 1;
	}

	void doDamage(LivingEntity e) {
		// minor modification here, the shots are quite strong
		// so I've made it so they only do half damage against player entities.
		e.hurt(getDamageSource(e), (e instanceof Player ? 0.5F : 1F) * adjustDamageForPotionShots(getDamageOfShot(e)));
	}

	protected DamageSource getDamageSource(LivingEntity livingEntity) {
		return livingEntity.damageSources().source(ModEntities.BULLET_DAMAGE_TYPE, getOwner(), this);
	}

	private float adjustDamageForPotionShots(int damageOfShot) {
		return potionContents.hasEffects() ? 4 : damageOfShot; // setting the cap to damage 4 for potion shots
	}

	protected void spawnMotionBasedParticle(ParticleOptions particleData) {
		spawnMotionBasedParticle(particleData, getY());
	}

	protected void spawnMotionBasedParticle(ParticleOptions particleData, double y) {
		Vec3 motion = getDeltaMovement();
		level().addParticle(particleData, getX(), y, getZ(), gaussian((float) motion.x()), gaussian((float) motion.y()), gaussian((float) motion.z()));
	}

	protected void groundImpact(Direction sideHit) {
		ricochet(sideHit);
	}

	/**
	 * @param d
	 *            is the factor of the double
	 * @return a negative or positive value with limits of 50% of d
	 */
	protected double smallGauss(double d) {
		return (level().random.nextFloat() - 0.5D) * d;
	}

	/**
	 * @param d
	 *            is the factor of the double
	 * @return a positive value between 0% and 50% of d
	 */
	float posGauss(float d) {
		return random.nextFloat() * 0.5F * d;
	}

	double posGauss(double d) {
		return random.nextFloat() * 0.5D * d;
	}

	/**
	 * @param d
	 *            haphazardly determines the upper bounds of the [always positive] gaussian
	 * @return a [comparatively] normal gaussian ranging from 75% to 125% of the parameter d
	 */
	float gaussian(float d) {
		return d + d * ((random.nextFloat() - 0.5F) / 4);
	}

	double gaussian(double d) {
		return d + d * (random.nextFloat() - 0.5F);
	}

	/**
	 * @param d
	 *            haphazardly determines the upper bounds of the [always positive] gaussian
	 * @return a [comparatively] low gaussian ranging from 25% to 75% of the parameter d
	 */
	double lowGauss(double d) {
		return d - d * (random.nextFloat() / 4 + 0.5);
	}

	/**
	 * Handles the ricochet "event", more or less determines when the entity does or doesn't ricochet. If the ricochet limit is set to 0, it will still
	 * "ricochet" once, but will immediately self destruct by calling its burstEffect and setting itself to dead.
	 */
	private void ricochet(Direction sideHit) {
		switch (sideHit) {
			case DOWN, UP -> setDeltaMovement(getDeltaMovement().multiply(1, -1, 1));
			case WEST, EAST -> setDeltaMovement(getDeltaMovement().multiply(-1, 1, 1));
			case SOUTH, NORTH -> setDeltaMovement(getDeltaMovement().multiply(1, 1, -1));
			default -> {
				/* noop */}
		}
		ricochetCounter++;
		if (ricochetCounter > getRicochetMax()) {
			doBurstEffect(sideHit);
			scheduledForDeath = true;
			for (int particles = 0; particles < 4; particles++) {
				switch (sideHit) {
					case DOWN -> level().addParticle(ParticleTypes.SMOKE, getX(), getY(), getZ(), gaussian(0.1F), -gaussian(0.1F), gaussian(0.1F));
					case UP, SOUTH, EAST -> level().addParticle(ParticleTypes.SMOKE, getX(), getY(), getZ(), gaussian(0.1F), gaussian(0.1F), gaussian(0.1F));
					case NORTH -> level().addParticle(ParticleTypes.SMOKE, getX(), getY(), getZ(), gaussian(0.1F), gaussian(0.1F), -gaussian(0.1F));
					case WEST -> level().addParticle(ParticleTypes.SMOKE, getX(), getY(), getZ(), -gaussian(0.1F), gaussian(0.1F), gaussian(0.1F));
					default -> {
						/* noop */}
				}
			}
		}
	}

	/*
	 * custom seek method, currently only being used in seeker and ender shots. it could be better, but it works. As of writing this, both shots share the same
	 * formulas.
	 */
	void seekTarget() {
		Entity closestTarget = null;
		Set<String> huntableEntitiesBlacklist = new HashSet<>(Config.COMMON.items.seekerShot.huntableEntitiesBlacklist.get());
		List<Entity> targetsList = level().getEntities(this, new AABB(getX() - 5, getY() - 5, getZ() - 5, getX() + 5, getY() + 5, getZ() + 5),
				Mob.class::isInstance);
		Iterator<Entity> iTarget = targetsList.iterator();
		double closestDistance = Double.MAX_VALUE;
		while (iTarget.hasNext()) {
			Entity currentTarget = iTarget.next();

			String entityName = RegistryHelper.getRegistryName(currentTarget).toString();
			if (huntableEntitiesBlacklist.contains(entityName) || (currentTarget == getOwner())
					|| (!currentTarget.isAlive() || (currentTarget instanceof LivingEntity living && living.getHealth() <= 0))) {
				continue;
			}
			// goes for the closest thing it can
			if (distanceTo(currentTarget) < closestDistance) {
				closestDistance = distanceTo(currentTarget);
				closestTarget = currentTarget;
			}
		}
		// these are extremely touchy, tune them lightly.
		if (closestTarget != null && getOwner() != null) {
			double x = closestTarget.getBoundingBox().minX + closestTarget.getBoundingBox().maxX;
			x /= 2D;
			double y = closestTarget.getBoundingBox().minY + closestTarget.getBoundingBox().maxY;
			y /= 2D;
			double z = closestTarget.getBoundingBox().minZ + closestTarget.getBoundingBox().maxZ;
			z /= 2D;
			double trueX = getBoundingBox().minX + getBoundingBox().maxX;
			trueX /= 2D;
			double trueY = getBoundingBox().minY + getBoundingBox().maxY;
			trueY /= 2D;
			double trueZ = getBoundingBox().minZ + getBoundingBox().maxZ;
			trueZ /= 2D;
			Vec3 seekVector = new Vec3(x - trueX, y - trueY, z - trueZ);
			seekVector = seekVector.normalize();
			setDeltaMovement(seekVector.multiply(0.4D, 0.4D, 0.4D));

			if (level().isClientSide) {
				lerpMotion(getDeltaMovement().x(), getDeltaMovement().y(), getDeltaMovement().z());
			}
		}
	}

	/**
	 * Determines the maximum number of bounces a bullet gets before burstEffect + dying. 0 means it is destroyed the moment it makes impact. This only matters
	 * if you actually call "groundImpact" from your onImpact(MOP) method.
	 */
	abstract int getRicochetMax();

	/**
	 * @param e
	 *            an optional parameter, some shots need to know what entity they're hitting for damage counts
	 * @return the int of damage the shot should deal. Most of these use my "dX" methods of this class to randomize damage, to a degree.
	 */
	abstract int getDamageOfShot(LivingEntity e);

	/**
	 * Additional entity impact effects should go here
	 *
	 * @param livingEntity
	 *            the entity being struck
	 */
	protected void onImpact(LivingEntity livingEntity) {
		if (!level().isClientSide) {
			if (livingEntity != getOwner() || ticksInAir > 3) {
				doDamage(livingEntity);
			}
			spawnHitParticles(8);
			scheduledForDeath = true;
		}
	}

	@Override
	protected void onHit(HitResult result) {
		if (result.getType() == HitResult.Type.ENTITY) {
			Entity entity = ((EntityHitResult) result).getEntity();
			if (entity == getOwner() || !(entity instanceof LivingEntity)) {
				return;
			}
			onImpact((LivingEntity) entity);
		} else if (result.getType() == HitResult.Type.BLOCK) {
			groundImpact(((BlockHitResult) result).getDirection());
		}
	}

	/**
	 * This is the effect called when the shot reaches the ground and has no ricochets remaining. It can also be called at any time by hooking into
	 * flight/firing effects.
	 *
	 * @param sideHit
	 *            is sometimes used when you need particles to fly in a certain direction.
	 */
	abstract void doBurstEffect(Direction sideHit);

	/**
	 * The particle/effect window when the gun is initially fired, between "ticksAlive" 1 and 3.
	 */
	abstract void doFiringEffects();

	/**
	 * The particle/effect window any time after the initial firing window of doFiringEffects. (ticksAlive >= 3)
	 */
	abstract void doFlightEffects();

	/**
	 * The particles which spawn when the bullet impacts an entity.
	 *
	 * @param i
	 *            the number of times you want the inner for loop to produce a single particle at random velocity
	 */
	abstract void spawnHitParticles(int i);

	// used by the renderer to pull the shot texture directly from the entity.
	// This might not work.
	public abstract ResourceLocation getShotTexture();
}

package reliquary.init;

import com.mojang.serialization.Codec;
import net.minecraft.core.BlockPos;
import net.minecraft.core.component.DataComponentType;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.ExtraCodecs;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.fluids.SimpleFluidContent;
import net.neoforged.neoforge.registries.DeferredRegister;
import reliquary.Reliquary;
import reliquary.item.*;
import reliquary.item.component.OversizedItemContainerContents;
import reliquary.util.CodecHelper;

import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;

public class ModDataComponents {
	private static final DeferredRegister<DataComponentType<?>> DATA_COMPONENT_TYPES = DeferredRegister.create(BuiltInRegistries.DATA_COMPONENT_TYPE,
			Reliquary.MOD_ID);

	public static final Supplier<DataComponentType<ResourceLocation>> ENTITY_NAME = DATA_COMPONENT_TYPES.register("entity_name",
			() -> new DataComponentType.Builder<ResourceLocation>().persistent(ResourceLocation.CODEC).networkSynchronized(ResourceLocation.STREAM_CODEC)
					.build());

	public static final Supplier<DataComponentType<SimpleFluidContent>> FLUID_CONTENTS = DATA_COMPONENT_TYPES.register("fluid_contents",
			() -> new DataComponentType.Builder<SimpleFluidContent>().persistent(SimpleFluidContent.CODEC).networkSynchronized(SimpleFluidContent.STREAM_CODEC)
					.build());

	public static final Supplier<DataComponentType<OversizedItemContainerContents>> OVERSIZED_ITEM_CONTAINER_CONTENTS = DATA_COMPONENT_TYPES
			.register("oversized_item_container_contents", () -> new DataComponentType.Builder<OversizedItemContainerContents>()
					.persistent(OversizedItemContainerContents.CODEC).networkSynchronized(OversizedItemContainerContents.STREAM_CODEC).build());

	public static final Supplier<DataComponentType<Map<Integer, Integer>>> PARTIAL_CHARGES = DATA_COMPONENT_TYPES.register("partial_charge",
			() -> new DataComponentType.Builder<Map<Integer, Integer>>().persistent(ChargeableItem.PARTIAL_CHARGES_CODEC)
					.networkSynchronized(ChargeableItem.PARTIAL_CHARGES_STREAM_CODEC).build());

	public static final Supplier<DataComponentType<BlockPos>> WARP_POSITION = DATA_COMPONENT_TYPES.register("warp_position",
			() -> new DataComponentType.Builder<BlockPos>().persistent(BlockPos.CODEC).networkSynchronized(BlockPos.STREAM_CODEC).build());

	public static final Supplier<DataComponentType<ResourceLocation>> WARP_DIMENSION = DATA_COMPONENT_TYPES.register("warp_dimension",
			() -> new DataComponentType.Builder<ResourceLocation>().persistent(ResourceLocation.CODEC).networkSynchronized(ResourceLocation.STREAM_CODEC)
					.build());

	public static final Supplier<DataComponentType<Set<BlockPos>>> FROZEN_POSITIONS = DATA_COMPONENT_TYPES.register("frozen_positions",
			() -> new DataComponentType.Builder<Set<BlockPos>>().persistent(CodecHelper.setOf(BlockPos.CODEC))
					.networkSynchronized(BlockPos.STREAM_CODEC.apply(ByteBufCodecs.collection(HashSet::new))).build());

	public static final Supplier<DataComponentType<Integer>> CHARGE = DATA_COMPONENT_TYPES.register("charge",
			() -> new DataComponentType.Builder<Integer>().persistent(ExtraCodecs.NON_NEGATIVE_INT).networkSynchronized(ByteBufCodecs.INT).build());

	public static final Supplier<DataComponentType<Integer>> GUNPOWDER = DATA_COMPONENT_TYPES.register("gunpowder",
			() -> new DataComponentType.Builder<Integer>().persistent(ExtraCodecs.NON_NEGATIVE_INT).networkSynchronized(ByteBufCodecs.INT).build());

	public static final Supplier<DataComponentType<EnderStaffItem.Mode>> ENDER_STAFF_MODE = DATA_COMPONENT_TYPES.register("ender_staff_mode",
			() -> new DataComponentType.Builder<EnderStaffItem.Mode>().persistent(EnderStaffItem.Mode.CODEC)
					.networkSynchronized(EnderStaffItem.Mode.STREAM_CODEC).build());

	public static final Supplier<DataComponentType<Boolean>> ENABLED = DATA_COMPONENT_TYPES.register("enabled",
			() -> new DataComponentType.Builder<Boolean>().persistent(Codec.BOOL).networkSynchronized(ByteBufCodecs.BOOL).build());

	public static final Supplier<DataComponentType<Integer>> SNOWBALLS = DATA_COMPONENT_TYPES.register("snowballs",
			() -> new DataComponentType.Builder<Integer>().persistent(ExtraCodecs.NON_NEGATIVE_INT).networkSynchronized(ByteBufCodecs.INT).build());

	public static final Supplier<DataComponentType<Short>> BULLET_COUNT = DATA_COMPONENT_TYPES.register("bullet_count",
			() -> new DataComponentType.Builder<Short>().persistent(Codec.SHORT).networkSynchronized(ByteBufCodecs.SHORT).build());

	public static final Supplier<DataComponentType<ResourceLocation>> MAGAZINE_TYPE = DATA_COMPONENT_TYPES.register("magazine_type",
			() -> new DataComponentType.Builder<ResourceLocation>().persistent(ResourceLocation.CODEC).networkSynchronized(ResourceLocation.STREAM_CODEC)
					.build());

	public static final Supplier<DataComponentType<Long>> COOLDOWN_TIME = DATA_COMPONENT_TYPES.register("cooldown_time",
			() -> new DataComponentType.Builder<Long>().persistent(Codec.LONG).networkSynchronized(ByteBufCodecs.VAR_LONG).build());

	public static final Supplier<DataComponentType<Byte>> PLANTABLE_INDEX = DATA_COMPONENT_TYPES.register("plantable_index",
			() -> new DataComponentType.Builder<Byte>().persistent(Codec.BYTE).networkSynchronized(ByteBufCodecs.BYTE).build());

	public static final Supplier<DataComponentType<HarvestRodItem.Mode>> HARVEST_ROD_MODE = DATA_COMPONENT_TYPES.register("harvest_rod",
			() -> new DataComponentType.Builder<HarvestRodItem.Mode>().persistent(HarvestRodItem.Mode.CODEC)
					.networkSynchronized(HarvestRodItem.Mode.STREAM_CODEC).build());

	public static final Supplier<DataComponentType<Integer>> EXPERIENCE = DATA_COMPONENT_TYPES.register("experience",
			() -> new DataComponentType.Builder<Integer>().persistent(ExtraCodecs.NON_NEGATIVE_INT).networkSynchronized(ByteBufCodecs.INT).build());

	public static final Supplier<DataComponentType<Integer>> DRAIN_XP_LEVELS = DATA_COMPONENT_TYPES.register("drain_xp_levels",
